@extends('layouts.app')
@section('title', 'Catalog | Inchangs Boutique')
@section('content')
<header class="page-head"><div><p class="eyebrow">Admin</p><h1>Catalog Management</h1></div></header><section class="split"><div class="panel"><h2>Category Form</h2><form id="categoryForm" class="form-grid"><input type="hidden" name="id"><label>Name<input name="name" required></label><label>Description<input name="description"></label><label>Status<select name="status"><option>active</option><option>inactive</option></select></label><button class="btn primary">Save Category</button><button type="button" class="btn ghost" onclick="resetCategory()">Clear</button></form></div><div class="panel"><h2>Product Form</h2><form id="productForm" class="form-grid"><input type="hidden" name="id"><label>Category<select name="category_id" id="productCategory" required></select></label><label>Name<input name="name" required></label><label>SKU<input name="sku" required></label><label>Price<input type="number" name="price" min="1" step="0.01" required></label><label>Stock<input type="number" name="stock" min="0" required></label><label>Size<input name="size"></label><label>Color<input name="color"></label><label>Image URL<input type="url" name="image_url"></label><label>Description<textarea name="description"></textarea></label><label>Status<select name="status"><option>active</option><option>inactive</option></select></label><button class="btn primary">Save Product</button><button type="button" class="btn ghost" onclick="resetProduct()">Clear</button></form></div></section><section class="panel"><h2>Categories</h2><table id="categoriesTable" class="display"><thead><tr><th>ID</th><th>Name</th><th>Status</th><th>Action</th></tr></thead></table></section><section class="panel"><h2>Products</h2><table id="productsTable" class="display"><thead><tr><th>ID</th><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead></table></section>
@endsection
@push('scripts')<script>let categoriesTable,productsTable;function fillCategories(){$.getJSON('/api/categories',res=>{$('#productCategory').html(res.data.map(c=>`<option value="${c.id}">${c.name}</option>`));});}function resetCategory(){$('#categoryForm')[0].reset();$('#categoryForm [name=id]').val('');}function resetProduct(){$('#productForm')[0].reset();$('#productForm [name=id]').val('');}function editCategory(row){Object.keys(row).forEach(k=>$('#categoryForm [name='+k+']').val(row[k]));}function editProduct(row){Object.keys(row).forEach(k=>$('#productForm [name='+k+']').val(row[k]));}$(function(){fillCategories();categoriesTable=$('#categoriesTable').DataTable({ajax:'/api/categories',columns:[{data:'id'},{data:'name'},{data:'status'},{data:null,render:(d)=>`<button class="btn mini" onclick='editCategory(${JSON.stringify(d)})'>Edit</button><button class="btn mini danger" onclick="ajaxDelete('/api/categories/${d.id}',()=>{categoriesTable.ajax.reload();fillCategories();})">Delete</button>`}]});productsTable=$('#productsTable').DataTable({ajax:'/api/products',columns:[{data:'id'},{data:'name'},{data:'category'},{data:'price'},{data:'stock'},{data:'status'},{data:null,render:(d)=>`<button class="btn mini" onclick='editProduct(${JSON.stringify(d)})'>Edit</button><button class="btn mini danger" onclick="ajaxDelete('/api/products/${d.id}',()=>productsTable.ajax.reload())">Delete</button>`}]});$('#categoryForm').on('submit',function(e){e.preventDefault();const id=$('[name=id]',this).val();ajaxForm(id?'/api/categories/'+id:'/api/categories',id?'PUT':'POST',$(this).serialize(),()=>{resetCategory();categoriesTable.ajax.reload();fillCategories();});});$('#productForm').on('submit',function(e){e.preventDefault();const id=$('[name=id]',this).val();ajaxForm(id?'/api/products/'+id:'/api/products',id?'PUT':'POST',$(this).serialize(),()=>{resetProduct();productsTable.ajax.reload();});});});</script>@endpush
